package com.gymflow.app;
import android.app.*; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import org.json.*;
public class EquipmentActivity extends AppCompatActivity{
 private LinearLayout list;
 @Override protected void onCreate(Bundle b){super.onCreate(b);ScrollView s=new ScrollView(this);LinearLayout r=Ui.page(this);s.addView(r);Ui.backHeader(this,r,"Equipamiento");r.addView(Ui.subtitle(this,"Cargá las máquinas y elementos reales. Las rutinas se filtrarán usando esta lista."));Button add=Ui.button(this,"+ Agregar equipamiento");add.setOnClickListener(v->dialog());r.addView(add);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);r.addView(list);load();setContentView(s);}
 private void load(){list.removeAllViews();list.addView(Ui.subtitle(this,"Cargando..."));Cloud.get(this,"gf_equipment","select=id,name,type,muscle_group,available&owner_id=eq."+Session.uid(this)+"&order=name.asc",(c,b)->{list.removeAllViews();try{JSONArray a=new JSONArray(b);if(a.length()==0)list.addView(Ui.card(this,"Sin equipamiento","Agregá la primera máquina del gimnasio."));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String id=o.optString("id"),name=o.optString("name");TextView t=Ui.card(this,name,o.optString("type","Máquina")+" · "+o.optString("muscle_group","Sin grupo"));t.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(name).setMessage("¿Eliminar este equipamiento?").setNegativeButton("Cancelar",null).setPositiveButton("Eliminar",(d,w)->Cloud.delete(this,"gf_equipment","id=eq."+id,(cc,bb)->load())).show());list.addView(t);}}catch(Exception e){list.addView(Ui.card(this,"Error al cargar",Cloud.err(b)));}});}
 private void dialog(){LinearLayout box=Ui.page(this);EditText name=Ui.input(this,"Ej: Prensa 45°");box.addView(name);Spinner type=Ui.spinner(this,new String[]{"Máquina","Banco","Polea","Barra","Mancuerna","Otro"});box.addView(type);EditText muscle=Ui.input(this,"Grupo muscular principal");box.addView(muscle);new AlertDialog.Builder(this).setTitle("Agregar equipamiento").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{String n=name.getText().toString().trim();if(n.isEmpty())return;JSONObject o=new JSONObject();o.put("owner_id",Session.uid(this));o.put("name",n);o.put("type",type.getSelectedItem().toString());o.put("muscle_group",muscle.getText().toString().trim());Cloud.post(this,"gf_equipment",o,(c,b)->{if(c>=200&&c<300)load();else Toast.makeText(this,Cloud.err(b),Toast.LENGTH_LONG).show();});}catch(Exception ignored){}}).show();}
}
